              seen.add((a,b)); st.append((a,b))
        r0=min(x for x,y in cells); r1=max(x for x,y in cells); c0=min(y for x,y in cells); c1=max(y for x,y in cells)
        marks=[(x,y) for x,y in cells if g[x][y] not in (0,8)]
        if not marks: continue
        mr0=min(x for x,y in marks); mr1=max(x for x,y in marks); mc0=min(y for x,y in marks); mc1=max(y for x,y in marks)
        ph=mr1-mr0+1; pw=mc1-mc0+1
        if (r1-r0+1)%ph or (c1-c0+1)%pw: continue
